<script>document.querySelectorAll('[data-password-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.target);const visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'Hide':'Show';button.setAttribute('aria-label',visible?'Hide password':'Show password');button.setAttribute('aria-pressed',String(visible))}));function showTab(tab){for(const id of ['login','register','verify'])document.getElementById(id).classList.toggle('hidden',id!==tab);document.getElementById('resendForm').classList.toggle('hidden',tab!=='verify');document.getElementById('modeTitle').textContent=({login:'● Sign in to your account',register:'● Create your account',verify:'● Verify your Gmail address'})[tab]}function toggleTheme(){let dark=document.body.classList.toggle('dark');localStorage.setItem('cec-theme',dark?'dark':'light');document.getElementById('themeBtn').textContent=dark?'☀️ Light mode':'🌙 Dark mode'}if(localStorage.getItem('cec-theme')==='dark')toggleTheme();@if(session('registration_code_sent'))showTab('verify');@elseif(old('name') || $errors->has('email') || $errors->has('name') || $errors->has('username') || $errors->has('password'))showTab('register');@endif</script></body></html>